/bin/bash -lc "cat >> packages/components/containers/payments/paymentTokenHelper.test.ts <<'EOF'

describe('createPaymentToken verification strategy', () => {
    const api = jest.fn();
    const verify = jest.fn();
    const params = { PaymentMethodID: 'existing' };

    beforeEach(() => {
        api.mockReset();
        verify.mockReset();
    });

    it('returns a chargeable token without verification', async () => {
        const { getCreatePaymentToken } = await import('./paymentTokenHelper');
        api.mockResolvedValue({ Token: 'ready', Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });
        const result = await getCreatePaymentToken(verify)({ api, params });
        expect(result.Payment.Details.Token).toBe('ready');
        expect(verify).not.toHaveBeenCalled();
    });

    it('passes pending tokens to the injected verification strategy', async () => {
        const { getCreatePaymentToken } = await import('./paymentTokenHelper');
        api.mockResolvedValue({ Token: 'pending', Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING, ApprovalURL: 'url', ReturnHost: 'host' });
        const verified = { Payment: { Details: { Token: 'pending' } } };
        verify.mockResolvedValue(verified);
        await expect(getCreatePaymentToken(verify)({ api, params, mode: 'add-card' })).resolves.toBe(verified);
        expect(verify).toHaveBeenCalledWith({ mode: 'add-card', Payment: undefined, Token: 'pending', ApprovalURL: 'url', ReturnHost: 'host' });
    });

    it('rejects a failed initial token without opening verification', async () => {
        const { getCreatePaymentToken } = await import('./paymentTokenHelper');
        api.mockResolvedValue({ Token: 'failed', Status: PAYMENT_TOKEN_STATUS.STATUS_FAILED });
        await expect(getCreatePaymentToken(verify)({ api, params })).rejects.toThrow('Payment process failed');
        expect(verify).not.toHaveBeenCalled();
    });
});
EOF
